// Per-setup cost statistics for the business plan's unit economics. See docs/DESIGN.md §"Book (cfo.ai)"
// and the `cost_usd` row of §"Data model": a row priced on an unknown model carries `cost = null`, so
// nulls are data (how often a setup could not be priced) and never enter the money statistics.

/** One priced row: the setup it belongs to and its cost, or `null` when the model was unknown. */
export interface CostRow {
  setup: string;
  costUsd: number | null;
}

/** Cost totals and spread for one setup. `n` counts the priced rows; `nullCount` the unpriced ones. */
export interface CostStats {
  setup: string;
  n: number;
  nullCount: number;
  totalUsd: number;
  meanUsd: number | null;
  p50Usd: number | null;
  p90Usd: number | null;
}

/** Money is reported to 4 decimals, the precision the stored costs keep. */
const DECIMALS = 4;

/**
 * Cost totals and spread per setup.
 *
 * Rows are grouped by `setup` and sorted by it. A `null` cost is counted in `nullCount` and excluded
 * from every statistic, so `n` is the number of priced rows: with no priced rows `totalUsd` is 0 and
 * `meanUsd`, `p50Usd` and `p90Usd` are `null`. Percentiles are nearest-rank over the ascending priced
 * values: rank = ceil(p * n), clamped to at least 1, and read at index rank - 1. Money is rounded to
 * 4 decimals after summing or averaging, never before, so one row's rounding cannot drift the total.
 */
export function costStats(rows: CostRow[]): CostStats[] {
  const priced = new Map<string, number[]>();
  const nulls = new Map<string, number>();
  const setups = new Set<string>();

  for (const row of rows) {
    setups.add(row.setup);
    if (row.costUsd === null) {
      nulls.set(row.setup, (nulls.get(row.setup) ?? 0) + 1);
      continue;
    }
    const values = priced.get(row.setup);
    if (values === undefined) priced.set(row.setup, [row.costUsd]);
    else values.push(row.costUsd);
  }

  return [...setups].sort().map((setup) => {
    const values = (priced.get(setup) ?? []).sort((a, b) => a - b);
    const n = values.length;
    const total = values.reduce((sum, value) => sum + value, 0);
    return {
      setup,
      n,
      nullCount: nulls.get(setup) ?? 0,
      totalUsd: round(total),
      meanUsd: n === 0 ? null : round(total / n),
      p50Usd: percentile(values, 0.5),
      p90Usd: percentile(values, 0.9),
    };
  });
}

/** Nearest-rank percentile of `sorted` (ascending), or `null` when there is nothing to rank. */
function percentile(sorted: number[], p: number): number | null {
  if (sorted.length === 0) return null;
  const rank = Math.max(1, Math.ceil(p * sorted.length));
  return round(sorted[rank - 1]);
}

/** Rounds to {@link DECIMALS} decimals, normalizing -0 to 0. */
function round(value: number): number {
  const factor = 10 ** DECIMALS;
  const rounded = Math.round(value * factor) / factor;
  return rounded === 0 ? 0 : rounded;
}

import { describe, expect, test } from "bun:test";
import { costStats } from "../src/report/costs.ts";

// Cost rows are the priced side of a run: a setup id and its cost, or null when the model is unknown
// (see docs/DESIGN.md §"Data model": Copilot CLI and Factory Droid record no tokens, so cost = null).
describe("costStats", () => {
  test("returns an empty array for no rows", () => {
    expect(costStats([])).toEqual([]);
  });

  test("returns one row per setup, sorted by setup", () => {
    const stats = costStats([
      { setup: "z", costUsd: 1 },
      { setup: "a", costUsd: 2 },
      { setup: "m", costUsd: 3 },
    ]);
    expect(stats.map((s) => s.setup)).toEqual(["a", "m", "z"]);
    expect(stats).toHaveLength(3);
  });

  test("counts nulls but excludes them from n, total, mean and percentiles", () => {
    const stats = costStats([
      { setup: "a", costUsd: 10 },
      { setup: "a", costUsd: null },
      { setup: "a", costUsd: 30 },
    ]);
    expect(stats[0]).toEqual({
      setup: "a",
      n: 2,
      nullCount: 1,
      totalUsd: 40,
      meanUsd: 20,
      p50Usd: 10,
      p90Usd: 30,
    });
  });

  test("a setup whose rows are all null keeps its row with null statistics", () => {
    const stats = costStats([
      { setup: "b", costUsd: null },
      { setup: "b", costUsd: null },
    ]);
    expect(stats).toEqual([
      { setup: "b", n: 0, nullCount: 2, totalUsd: 0, meanUsd: null, p50Usd: null, p90Usd: null },
    ]);
  });

  test("keeps setup ids that appear only as nulls distinct from absent ones", () => {
    const stats = costStats([
      { setup: "priced", costUsd: 5 },
      { setup: "unpriced", costUsd: null },
    ]);
    expect(stats.map((s) => s.setup)).toEqual(["priced", "unpriced"]);
  });

  test("percentiles are nearest-rank on the ascending non-null values", () => {
    // 5 values: rank = ceil(0.5 * 5) = 3 and ceil(0.9 * 5) = 5.
    const stats = costStats([
      { setup: "x", costUsd: 5 },
      { setup: "x", costUsd: 1 },
      { setup: "x", costUsd: 4 },
      { setup: "x", costUsd: 2 },
      { setup: "x", costUsd: 3 },
    ]);
    expect(stats[0].p50Usd).toBe(3);
    expect(stats[0].p90Usd).toBe(5);
  });

  test("percentiles use the upper rank for an even number of values", () => {
    // 4 values: rank = ceil(0.5 * 4) = 2 and ceil(0.9 * 4) = 4, never an average of two neighbours.
    const stats = costStats([
      { setup: "x", costUsd: 1 },
      { setup: "x", costUsd: 2 },
      { setup: "x", costUsd: 3 },
      { setup: "x", costUsd: 4 },
    ]);
    expect(stats[0].p50Usd).toBe(2);
    expect(stats[0].p90Usd).toBe(4);
  });

  test("a single priced row is its own median and p90", () => {
    const stats = costStats([{ setup: "x", costUsd: 2.5 }]);
    expect(stats[0].p50Usd).toBe(2.5);
    expect(stats[0].p90Usd).toBe(2.5);
  });

  test("rounds money to 4 decimals after summing, not per row", () => {
    // Rounding each row first would give total 1.2346 + 2.3457 = 3.5803, not 3.5802.
    const stats = costStats([
      { setup: "x", costUsd: 1.23456 },
      { setup: "x", costUsd: 2.34567 },
    ]);
    expect(stats[0].totalUsd).toBe(3.5802);
    expect(stats[0].meanUsd).toBe(1.7901);
    expect(stats[0].p50Usd).toBe(1.2346);
    expect(stats[0].p90Usd).toBe(2.3457);
  });

  test("sums many small costs without losing the total to per-row rounding", () => {
    const rows = Array.from({ length: 1000 }, () => ({ setup: "x", costUsd: 0.00004 }));
    const stats = costStats(rows);
    expect(stats[0].n).toBe(1000);
    expect(stats[0].totalUsd).toBe(0.04);
    expect(stats[0].meanUsd).toBe(0.0000);
  });

  test("does not mutate the caller's array or its order", () => {
    const rows = [
      { setup: "x", costUsd: 3 },
      { setup: "x", costUsd: 1 },
      { setup: "x", costUsd: 2 },
    ];
    costStats(rows);
    expect(rows.map((r) => r.costUsd)).toEqual([3, 1, 2]);
  });
});
